:root {
  --bg: #0d1712;
  --panel: rgba(17, 24, 20, 0.9);
  --panel-alt: rgba(24, 35, 29, 0.95);
  --panel-border: rgba(147, 200, 168, 0.16);
  --text: #edf6ee;
  --muted: #b6d0bf;
  --accent: #8ae3a4;
  --accent-2: #ffd166;
  --danger: #ff6b6b;
  --shadow: rgba(4, 7, 5, 0.46);
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  min-height: 100%;
  font-family: Inter, "Segoe UI", sans-serif;
  background:
    radial-gradient(circle at top, rgba(80, 112, 86, 0.35), transparent 30%),
    linear-gradient(180deg, #0c130e 0%, #101a13 100%);
  color: var(--text);
}

body {
  display: grid;
  place-items: center;
  min-height: 100vh;
  padding: 24px;
}

button {
  font: inherit;
}

.game-shell {
  width: min(1400px, 100%);
  background: rgba(10, 15, 12, 0.7);
  border: 1px solid var(--panel-border);
  border-radius: 22px;
  box-shadow: 0 34px 80px var(--shadow);
  overflow: hidden;
}

.hud {
  padding: 18px 20px 14px;
  background: rgba(14, 22, 17, 0.88);
  border-bottom: 1px solid var(--panel-border);
}

.title-row,
.stats-row,
.game-layout {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.title-row {
  margin-bottom: 16px;
}

.eyebrow {
  margin: 0 0 8px;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 0.15em;
  font-size: 11px;
  font-weight: 700;
}

h1 {
  margin: 0;
  font-size: clamp(1.8rem, 2vw, 2.5rem);
}

.restart {
  border: 1px solid rgba(138, 227, 164, 0.34);
  background: rgba(138, 227, 164, 0.14);
  color: var(--text);
  border-radius: 999px;
  padding: 10px 18px;
  cursor: pointer;
  transition: transform 120ms ease, background 120ms ease;
}

.restart:hover,
.craft-card button:hover {
  transform: translateY(-1px);
}

.stats-row {
  flex-wrap: wrap;
}

.stat {
  min-width: 120px;
  background: var(--panel-alt);
  border: 1px solid var(--panel-border);
  border-radius: 14px;
  padding: 10px 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat span {
  color: var(--muted);
  font-size: 0.76rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.stat strong {
  font-size: 1.4rem;
  font-weight: 800;
}

.game-layout {
  padding: 20px;
  align-items: flex-start;
}

.canvas-wrap {
  flex: 1;
  min-width: 0;
  background: rgba(12, 16, 13, 0.85);
  border: 1px solid var(--panel-border);
  border-radius: 18px;
  overflow: hidden;
  box-shadow: inset 0 0 24px rgba(0,0,0,0.2);
}

#gameCanvas {
  display: block;
  width: 100%;
  height: 560px;
  background: linear-gradient(180deg, #152820 0%, #1d3529 100%);
}

.panel {
  width: min(320px, 26vw);
  display: grid;
  gap: 14px;
}

.card {
  background: rgba(17, 24, 20, 0.92);
  border: 1px solid var(--panel-border);
  border-radius: 16px;
  padding: 16px;
  box-shadow: 0 12px 20px rgba(0, 0, 0, 0.12);
}

.card h2 {
  margin: 0 0 10px;
  font-size: 1rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent);
}

.objective-card p {
  margin: 0;
  line-height: 1.55;
  color: var(--text);
}

.inventory-card ul,
.log-card ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.inventory-card li,
.log-card li {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 0;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}

.inventory-card li:last-child,
.log-card li:last-child {
  border-bottom: none;
}

.inventory-card li span,
.log-card li span {
  color: var(--muted);
}

.craft-card {
  display: grid;
  gap: 10px;
}

.craft-card button {
  width: 100%;
  border: 1px solid rgba(255, 209, 102, 0.22);
  background: linear-gradient(180deg, rgba(255, 209, 102, 0.16), rgba(255, 209, 102, 0.08));
  color: var(--text);
  padding: 11px 12px;
  border-radius: 12px;
  cursor: pointer;
}

.log-card ul {
  max-height: 220px;
  overflow: auto;
}

.log-card li {
  display: block;
  color: var(--muted);
  line-height: 1.45;
}

@media (max-width: 1100px) {
  .game-layout {
    flex-direction: column;
  }

  .panel {
    width: 100%;
  }
}

@media (max-width: 700px) {
  body {
    padding: 12px;
  }

  .title-row {
    flex-direction: column;
    align-items: flex-start;
  }

  .stats-row {
    gap: 8px;
  }

  .stat {
    min-width: calc(50% - 8px);
  }

  #gameCanvas {
    height: 440px;
  }
}

